head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.spacYN = "N";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.pMenuID = $c.stf.InfoMenuID();
scwin.getPar, scwin.setPar;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        buttonSet.setDrftInfo(btn_Drft, scwin.drft); // 기안

        buttonSet.setInsertStatus();
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_Mst.insertRow();
        let strCodeCnt = "";
        if (js_market === "6") {
            cmb_SPECL_LIST_TP_CD.show("");
            cmb_PRE_LIST_TP_CD.show("");
            txa_DSC.show("");
            label_25.show("");
            label_26.show("");
            strCodeCnt = "코넥스시장상장규정 제28조 및 제33조^코넥스시장상장규정 제28조 및 제33조,직접 입력하세요^수기 입력";
            $c.elw.fn_searchCode();
        } else {
            cmb_SPECL_LIST_TP_CD.hide();
            cmb_PRE_LIST_TP_CD.hide();
            txa_DSC.hide();
            label_25.hide();
            label_26.hide();
            strCodeCnt = "유가증권시장상장규정 제48조^유가증권시장상장규정 제48조,코스닥시장상장규정 제23조 및 제54조^코스닥시장상장규정 제23조 및 제54조,코스닥시장상장규정 제23조 및 제82조^코스닥시장상장규정 제23조 및 제82조" + ",코스닥시장상장규정 제54조 및 제73조^코스닥시장상장규정 제54조 및 제73조,직접 입력하세요^수기 입력";
        }
        cmb_GRND_REGUL_NM.CBData = strCodeCnt;
        label_24.hide();
        label_18.show("");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.onpageload" });
    }
};

/**
 * @method
