/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("회사를 선택하세요");
        } else {
            scwin.initItem();
            await scwin.newReadSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05232.btn_New_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsur;
        scwin.setPar = scwin.setParIsur;

        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30
        if (scwin.pMenuID === "STF05232") {
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
        } else if (scwin.pMenuID === "STF05265") {
            // 기업인수목적 회사
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
            scwin.spacYN = "Y";
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05232.img_COM_NM_onclick" });
    }
};

