///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 기업인수목적 회사 구분
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    004048 -  특례상장구분코드
    04108 - 이전상장구분코드
     */
    const arrCid = [{
        cid: "SPECL_LIST_TP_CD",
        cnm: "cmb_SPECL_LIST_TP_CD"
    }, {
        cid: "PRE_LIST_TP_CD",
        cnm: "cmb_PRE_LIST_TP_CD"
    }];
    let objCod;
    let url = '';
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^선택,";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name newReadSync
 * @description new Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05232.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarketNew&inputMessageId=DELISTING_ISU_INOUT&ISUR_CD=" + txb_ISUR_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.stf.copyDataSet(dts_Isu, dts_Secu);
};

