    url += "&method=listMarketDetail&inputMessageId=DELISTING_INOUT&ISUR_CD=" + txb_ISUR_CD.getValue() + "&MKTACT_APPL_OBJ_TP_CD=2";
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/Delisting.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    url += "?SCREN_ID=" + "ULDSTF05232.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=masterDetail&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "?SCREN_ID=" + "ULDSTF05232.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listMarket&inputMessageId=DELISTING_ISU_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions2 = {
        id : "sbm_dts_Isu",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /* 2009.06.08 영문공시관련 추가 */
    url += "?SCREN_ID=" + "ULDSTF05232.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
