/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if (dts_Isu.getRowCount() === 0) {
        await $c.win.alert("[상장폐지 종목]을선택하세요");
        return false;
    }
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
        if (dts_Mst.getCellData(1, "DELIST_RSN_CD") === "") {
            await $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }

    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2" || scwin.vSPOT_ISU_TRD_MKT_TP_CD === "6") {
        if (txb_DELIST_RSN_DSC.getValue() === "") {
            await $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_DELIST_RSN_DSC, 2000, "상장폐지사유")) return false;
    }
    if (edt_DELIST_ADVNOTI_STRT_DD.getValue() !== "" || edt_DELIST_ADVNOTI_END_DD.getValue() !== "") {
        if (edt_DELIST_ADVNOTI_STRT_DD.getValue() === "") {
            await $c.win.alert("[상장폐지예고 시작일]을 입력하세요.");
            edt_DELIST_ADVNOTI_STRT_DD.focus();
            return false;
        }
        if (edt_DELIST_ADVNOTI_END_DD.getValue() === "") {
            await $c.win.alert("[상장폐지예고 종료일]을 입력하세요.");
            edt_DELIST_ADVNOTI_END_DD.focus();
            return false;
        }
        if (!$c.stf.compareFromToDate(edt_DELIST_ADVNOTI_STRT_DD, edt_DELIST_ADVNOTI_END_DD, "상장폐지예고 시작일", "상장폐지예고 종료일")) return false;
    }
    if (edt_ARRANTRD_MKTACT_ENFORCE_DD.getValue() !== "" || edt_ARRANTRD_END_DD.getValue() !== "") {
        if (edt_ARRANTRD_MKTACT_ENFORCE_DD.getValue() === "") {
            await $c.win.alert("[정리매매허용 시작일]을 입력하세요.");
            edt_ARRANTRD_MKTACT_ENFORCE_DD.focus();
            return false;
        }
        if (edt_ARRANTRD_END_DD.getValue() === "") {
            await $c.win.alert("[정리매매허용 종료일]을 입력하세요.");
            edt_ARRANTRD_END_DD.focus();
            return false;
        }
        if (!$c.stf.compareFromToDate(edt_ARRANTRD_MKTACT_ENFORCE_DD, edt_ARRANTRD_END_DD, "정리매매허용 시작일", "정리매매허용 종료일")) return false;
    }
    if (edt_DELIST_DD.getValue() === "") {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_DELIST_DD.getValue()) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (txb_GRND_REGUL_NM.getValue() === "") {
        await $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_GRND_REGUL_NM, 200, "근거규정")) return false;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
        if (dts_Mst.getCellData(1, "LIST_AGNCCOM_MBR_NO") === "") {
            await $c.win.alert("[상장주선인]를 선택하세요.");
            txb_MKTPARTC_KOR_NM.focus();
            return false;
        }
    }
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, txb_ISUR_CD.getValue(), edt_DELIST_DD.getValue(), scwin.vBzProcsNo, LIST_BZ_TP_CD_200)) {
        return false;
    }

    // 코넥스 이전상장구분 필수값 체크추가 jackal_22.06.24
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '6') {
        if (cmb_PRE_LIST_TP_CD.getValue() === "") {
            await $c.win.alert("[이전상장구분(코넥스)]를 선택하세요.");
            cmb_PRE_LIST_TP_CD.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Mst.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
        // alert('[dts_Mst]'+dts_Mst.text);
        await scwin.trs();
    }
};

