 */
scwin.dscl = async function() {
    if (!await scwin.checkBiz()) {
        return;
    }
    if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_Isu)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    let OldGet = scwin.getPar;
    const OldSet = scwin.setPar;

    /*
    fn_GetPar = function(arr, param_dts_isu, param_dts_mst,param_dts2,param_dts3) {
    	if (vSPOT_ISU_TRD_MKT_TP_CD == "1") {
    		arr[0] = "68051A";
    	} else if (vSPOT_ISU_TRD_MKT_TP_CD == "2") {
    		if ( fr_SecuGrpId == SECUGRP_ID_MF ) {
    			arr[0] = "70794";
    		} else {
    			arr[0] = "70769";
    		}
    	}
     */

    /* 2009.06.08 영문공시관련 추가 */
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
        // 유가
        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            arr[0] = "68051A";
            arr[1] = scwin.vBzProcsNo;
            arr[2] = txb_ISUR_CD.getValue();
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.copyDataSet(dts_Isu, param_dts_isu);
            $c.stf.copyDataSet(dts_Mst, param_dts_mst);
            $c.stf.copyDataSet(dts_Isu_Eng, param_dts_isu_eng);
            $c.stf.copyDataSet(dts_Mst_Eng, param_dts_mst_eng);
            return arr.length;
        };
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2" || scwin.vSPOT_ISU_TRD_MKT_TP_CD === "6") {
        // 코스닥,코넥스
        scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            if (scwin.fr_SecuGrpId === SECUGRP_ID_MF) {
                // 액면가가 무액면인지, '0'인지를 발행기관 테이블에서 판단
                // fn_getParval();
                if (dts_Isu.getCellData(1, "PARVAL") !== 0) {
                    arr[0] = "70794";
                } else {
                    // 무액면
                    arr[0] = "70794_P";
                }
                // alert("서식코드-->70794");

            } else {
                if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
                    arr[0] = "70769";
                } else {
                    arr[0] = "32007";
                }
                // alert("서식코드-->70769");

            }
            arr[1] = scwin.vBzProcsNo;
            arr[2] = txb_ISUR_CD.getValue();
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.copyDataSet(dts_Isu, param_dts_isu);
            if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "6") {
                if (cmb_SPECL_LIST_TP_CD.getValue() !== "") {
                    txb_MKTPARTC_KOR_NM.setValue($c.stf.getObjectText(cmb_SPECL_LIST_TP_CD));
                }
            }
            $c.stf.copyDataSet(dts_Mst, param_dts_mst);
            $c.stf.copyDataSet(dts_Isu_Eng, param_dts_isu_eng);
            $c.stf.copyDataSet(dts_Mst_Eng, param_dts_mst_eng);
            return arr.length;
        };
    }
    /* 2009.06.08 영문공시관련 추가 */

    scwin.setPar = function(arr) {

    };
    const wth = 750 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
    await scwin.listSync();
};

/**
 * @method
 * @name drft
 * @description drft 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.drft = async function() {
    if (!await scwin.checkBiz()) {
        return;
    }
    let OldGet = scwin.getPar;
    scwin.getPar = function(arr) {
        arr[0] = scwin.vBzProcsNo;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.getPar = OldGet;
};

// function fn_makt() { }

/**
 * @method
 * @name chkIsu
 * @description chk Isu 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkIsu = async function(row) {
    let chkIsu = false;
    if (dts_List.getCellData(row, "DISCLS_YN") === 'Y') {
        for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
            if (dts_Isu.getCellData(i, "LIST_SHRS") !== dts_Secu.getCellData(i, "LIST_SHRS")) {
                chkIsu = true;
            }
        }
    }
    if (chkIsu) {
        const res = window.confirm("상장주식수가 변경되었습니다. \n[수정] 처리를 하시겠습니까?");
        if (res) {
            LastJob = '수정';
            await scwin.newReadSync();
            await scwin.update2();
        }
    }
};
